TOTAL_STAGES=12
ENV_FILE="${WIZARD_ENV_FILE:-.env.staging}"

# ask_until KEY "Prompt" REGEX [secret] — re-ask until the paste looks right.
ask_until() {
  local key="$1" prompt="$2" re="$3" secret="${4:-}"
  while :; do
    if [[ -n "$secret" ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ "${!key}" =~ $re ]] && break
    warn "That doesn't look right — check you copied the whole value, then paste again."
  done
}

# to_clipboard VALUE [label] — put a value on the Windows clipboard so it can be pasted in the browser.
to_clipboard() {
  if command -v clip.exe >/dev/null 2>&1; then
    printf '%s' "$1" | clip.exe
    printf '  %s✓ copied to your clipboard%s %s\n' "$GREEN" "$RESET" "${2:-}"
  else
    warn "Couldn't copy automatically — copy it from $ENV_FILE instead."
  fi
}

random_secret() { node -e "process.stdout.write(require('crypto').randomBytes(48).toString('base64url'))"; }

